"""Style pass over the proposal deck: headings to plain labels, text and speaker notes to the
register of the paper. Run once against 68ca882; every replacement is asserted to match once."""
import json, pathlib, re, sys
proj = pathlib.Path(sys.argv[1]) / "project"

# slide id: (heading or None, [(old, new)], speaker notes)
